ExampleMonoBehaviour.cs<pre><code>using UnityEngine;
using UnityChart.Runtime;
using Random = UnityEngine.Random;

public class Test : MonoBehaviour
{
    private DataProvider provider;

    private void Start()
    {
        provider = new DataProvider(Color.blue, "Test Provider", "provider");
    }

    private void Update()
    {
        provider.AddDataPoint(Random.value * 10);
    }
}
</code></pre>

ExampleWindow.uxml<pre><code>&lt;ui:UXML xmlns:chart="UnityChart.Editor"
         xmlns:ui="UnityEngine.UIElements"
         xmlns:uie="UnityEditor.UIElements"&gt;

    &lt;chart:LineChart data-providers="provider"/&gt;

&lt;/ui:UXML&gt;
</code></pre> <p>This creates a simple line chart that reads data from the DataProvider with ID <code>provider</code>.</p>
